      BrowserDocumentRegion r = rm.nextCurrentRegion(_model.getNotifier());
      if (r != null) scrollToDocumentAndOffset(r.getDocument(), r.getStartOffset(), false, false);
      _configureBrowsing();
//      MainFrame.MFLOG.log("browseForward: "+rm);
    }
  };

