/**
 * An extension of JDesktopPane that supports often used MDI functionality. This
 * class also handles setting scroll bars for when windows move too far to the left or
 * bottom, providing the JMDIDesktopPane is in a ScrollPane.
 * Note by dnoyeb: I dont know why the container does not fire frame close events when the frames
 * are removed from the container with remove as opposed to simply closed with the
 * "x".  so if you say removeAll from container you wont be notified.  No biggie.
 *
 * @author Werner Randelshofer
 * Original version by 
 * Wolfram Kaiser (adapted from an article in JavaWorld), 
 * C.L.Gilbert <dnoyeb@users.sourceforge.net>
 * @version $Id: JMDIDesktopPane.java 717 2010-11-21 12:30:57Z rawcoder $
 */
public class JMDIDesktopPane extends JDesktopPane implements Arrangeable {
    private MDIDesktopManager manager;

    public JMDIDesktopPane() {
        manager = new MDIDesktopManager(this);
        setDesktopManager(manager);
        setDragMode(JDesktopPane.OUTLINE_DRAG_MODE);
        setAlignmentX(JComponent.LEFT_ALIGNMENT);
    }

    @Override
    public void setArrangement(Arrangeable.Arrangement newValue) {
        Arrangeable.Arrangement oldValue = getArrangement();
        switch (newValue) {
            case CASCADE :
                arrangeFramesCascading();
                break;
            case HORIZONTAL :
                arrangeFramesHorizontally();
                break;
            case VERTICAL :
                arrangeFramesVertically();
                break;
        }
        firePropertyChange("arrangement", oldValue, newValue);
    }


    @Override
    public Arrangeable.Arrangement getArrangement() {
        // FIXME Check for the arrangement of the JInternalFrames here
        // and return the true value
        return Arrangeable.Arrangement.CASCADE;
    }
    /**
     * Cascade all internal frames
     */
    private void arrangeFramesCascading() {
        JInternalFrame[] allFrames = getAllFrames();

        // do nothing if no frames to work with
        if (allFrames.length == 0) {
            return;
        }

        manager.setNormalSize();
        Insets insets = getInsets();
        int x = insets.left;
        int y = insets.top;
        int frameOffset=0;
        for (int i = allFrames.length - 1; i >= 0; i--) {
            Point p=SwingUtilities.convertPoint(allFrames[i].getContentPane(),0,0,allFrames[i]);
            frameOffset=Math.max(frameOffset,Math.max(p.x,p.y));
        }
        int frameHeight = (getBounds().height-insets.top-insets.bottom) - allFrames.length * frameOffset;
        int frameWidth = (getBounds().width-insets.left-insets.right) - allFrames.length * frameOffset;
        for (int i = allFrames.length - 1; i >= 0; i--) {
            try {
                allFrames[i].setMaximum(false);
            } catch (PropertyVetoException e) {
                e.printStackTrace();
            }

            allFrames[i].setBounds(x, y, frameWidth, frameHeight);
            x = x + frameOffset;
            y = y + frameOffset;
        }

        checkDesktopSize();
    }

    private void tileFramesHorizontally() {
        Component[] allFrames = getAllFrames();

        // do nothing if no frames to work with
        if (allFrames.length == 0) {
            return;
        }

        manager.setNormalSize();

        int frameHeight = getBounds().height/allFrames.length;
        int y = 0;
        for (int i = 0; i < allFrames.length; i++) {
            try {
                ((JInternalFrame)allFrames[i]).setMaximum(false);
            } catch (PropertyVetoException e) {
                e.printStackTrace();
            }

            allFrames[i].setBounds(0, y, getBounds().width,frameHeight);
            y = y + frameHeight;
        }

        checkDesktopSize();
    }

    public void tileFramesVertically() {
        Component[] allFrames = getAllFrames();

        // do nothing if no frames to work with
        if (allFrames.length == 0) {
            return;
        }
        manager.setNormalSize();

        int frameWidth = getBounds().width/allFrames.length;
        int x = 0;
        for (int i = 0; i < allFrames.length; i++) {
            try {
                ((JInternalFrame)allFrames[i]).setMaximum(false);
            } catch (PropertyVetoException e) {
                e.printStackTrace();
            }

            allFrames[i].setBounds(x, 0, frameWidth, getBounds().height);
            x = x + frameWidth;
        }

        checkDesktopSize();
    }

    /**
     * Arranges the frames as efficiently as possibly with preference for
     * keeping vertical size maximal.<br>
     *
     */
    public void arrangeFramesVertically() {
        Component[] allFrames = getAllFrames();
        // do nothing if no frames to work with
        if (allFrames.length == 0) {
            return;
        }

        manager.setNormalSize();

        int vertFrames = (int)Math.floor(Math.sqrt(allFrames.length));
        int horFrames = (int)Math.ceil(Math.sqrt(allFrames.length));

        // first arrange the windows that have equal size
        int frameWidth = getBounds().width / horFrames;
        int frameHeight = getBounds().height / vertFrames;
        int x = 0;
        int y = 0;
        int frameIdx = 0;
        for (int horCnt = 0; horCnt < horFrames-1; horCnt++) {
            y = 0;
            for (int vertCnt = 0; vertCnt < vertFrames; vertCnt++) {
                try {
                    ((JInternalFrame)allFrames[frameIdx]).setMaximum(false);
                } catch (PropertyVetoException e) {
                    e.printStackTrace();
                }

                allFrames[frameIdx].setBounds(x, y, frameWidth, frameHeight);
                frameIdx++;
                y = y + frameHeight;
            }
            x = x + frameWidth;
        }

        // the rest of the frames are tiled down on the last column with equal
        // height
        frameHeight = getBounds().height / (allFrames.length - frameIdx);
        y = 0;
        for (; frameIdx < allFrames.length; frameIdx++) {
            try {
                ((JInternalFrame)allFrames[frameIdx]).setMaximum(false);
            } catch (PropertyVetoException e) {
                e.printStackTrace();
            }

            allFrames[frameIdx].setBounds(x, y, frameWidth, frameHeight);
            y = y + frameHeight;
        }

        checkDesktopSize();
    }

    /**
     * Arranges the frames as efficiently as possibly with preference for
     * keeping horizontal size maximal.<br>
     *
     */
    public void arrangeFramesHorizontally() {
        Component[] allFrames = getAllFrames();
        // do nothing if no frames to work with
        if (allFrames.length == 0) {
            return;
        }

        manager.setNormalSize();

        int vertFrames = (int)Math.ceil(Math.sqrt(allFrames.length));
        int horFrames = (int)Math.floor(Math.sqrt(allFrames.length));

        // first arrange the windows that have equal size
        int frameWidth = getBounds().width / horFrames;
        int frameHeight = getBounds().height / vertFrames;
        int x = 0;
        int y = 0;
        int frameIdx = 0;
        for (int vertCnt = 0; vertCnt < vertFrames-1; vertCnt++) {
            x = 0;
            for (int horCnt = 0; horCnt < horFrames; horCnt++) {
                try {
                    ((JInternalFrame)allFrames[frameIdx]).setMaximum(false);
                } catch (PropertyVetoException e) {
                    e.printStackTrace();
                }

                allFrames[frameIdx].setBounds(x, y, frameWidth, frameHeight);
                frameIdx++;
                x = x + frameWidth;
            }
            y = y + frameHeight;
        }

        // the rest of the frames are tiled down on the last column with equal
        // height
        frameWidth = getBounds().width / (allFrames.length - frameIdx);
        x = 0;
        for (; frameIdx < allFrames.length; frameIdx++) {
            try {
                ((JInternalFrame)allFrames[frameIdx]).setMaximum(false);
            } catch (PropertyVetoException e) {
                e.printStackTrace();
            }

            allFrames[frameIdx].setBounds(x, y, frameWidth, frameHeight);
            x = x + frameWidth;
        }

        checkDesktopSize();
    }

    /**
     * Sets all component size properties ( maximum, minimum, preferred)
     * to the given dimension.
     */
    public void setAllSize(Dimension d) {
        setMinimumSize(d);
        setMaximumSize(d);
        setPreferredSize(d);
        setBounds(0, 0, d.width, d.height);
    }

    /**
     * Sets all component size properties ( maximum, minimum, preferred)
     * to the given width and height.
     */
    public void setAllSize(int width, int height) {
        setAllSize(new Dimension(width,height));
    }

    private void checkDesktopSize() {
        if ((getParent() != null) && isVisible()) {
            manager.resizeDesktop();
        }
    }

	public void show(final MDIApplication mdiApplication, final View v) {
	    if (!v.isShowing()) {
	        v.setShowing(true);
	        final JInternalFrame f = new JInternalFrame();
	        f.setDefaultCloseOperation(JInternalFrame.DO_NOTHING_ON_CLOSE);
	        f.setClosable(mdiApplication.getAction(v, CloseFileAction.ID) != null);
	        f.setMaximizable(true);
	        f.setResizable(true);
	        f.setIconifiable(false);
	        f.setSize(new Dimension(400, 400));
	        mdiApplication.updateViewTitle(v, f);

	        PreferencesUtil.installInternalFramePrefsHandler(mdiApplication.prefs, "view", f, this);
	        Point loc = new Point(getInsets().left, getInsets().top);
	        boolean moved;
	        do {
	            moved = false;
	            for (Iterator i = mdiApplication.views().iterator(); i.hasNext();) {
	                View aView = (View) i.next();
	                if (aView != v && aView.isShowing()
	                        && SwingUtilities.getRootPane(aView.getComponent()).getParent().
	                        getLocation().equals(loc)) {
	                    Point offset = SwingUtilities.convertPoint(SwingUtilities.getRootPane(aView.getComponent()), 0, 0, SwingUtilities.getRootPane(aView.getComponent()).getParent());
	                    loc.x += Math.max(offset.x, offset.y);
	                    loc.y += Math.max(offset.x, offset.y);
	                    moved = true;
	                    break;
	                }
	            }
	        } while (moved);
	        f.setLocation(loc);

	        //paletteHandler.add(f, v);

	        f.addInternalFrameListener(new InternalFrameAdapter() {

	            @Override
	            public void internalFrameClosing(final InternalFrameEvent evt) {
	                mdiApplication.getAction(v, CloseFileAction.ID).actionPerformed(
	                        new ActionEvent(f, ActionEvent.ACTION_PERFORMED,
	                        "windowClosing"));
	            }

	            @Override
	            public void internalFrameClosed(final InternalFrameEvent evt) {
	                v.stop();
	            }
	        });

	        v.addPropertyChangeListener(new PropertyChangeListener() {

	            @Override
	            public void propertyChange(PropertyChangeEvent evt) {
	                String name = evt.getPropertyName();
	                if (name == View.HAS_UNSAVED_CHANGES_PROPERTY
	                        || name == View.URI_PROPERTY) {
	                    mdiApplication.updateViewTitle(v, f);
	                }
	            }
	        });

	        f.addPropertyChangeListener(new PropertyChangeListener() {

	            @Override
	            public void propertyChange(PropertyChangeEvent evt) {
	                String name = evt.getPropertyName();
	                if (name.equals("selected")) {
	                    if (evt.getNewValue().equals(Boolean.TRUE)) {
	                        mdiApplication.setActiveView(v);
	                    } else {
	                        if (v == mdiApplication.getActiveView()) {
	                            mdiApplication.setActiveView(null);
	                        }
	                    }
	                }
	            }
	        });

	        //f.setJMenuBar(createMenuBar(v));

	        f.getContentPane().add(v.getComponent());
	        f.setVisible(true);
	        add(f);
	        if (getComponentCount() == 1) {
	            try {
	                f.setMaximum(true);
	            } catch (PropertyVetoException ex) {
	                // ignore veto
	            }
	        }
	        f.toFront();
	        try {
	            f.setSelected(true);
	        } catch (PropertyVetoException e) {
	            // Don't care.
	        }
	        v.getComponent().requestFocusInWindow();
	        v.start();
	    }
	}

}

/**
 * A <em>floating text area</em> that is used to edit a {@link TextHolderFigure}.
 *
 * <hr>
 * <b>Design Patterns</b>
 *
 * <p><em>Framework</em><br>
 * The text creation and editing tools and the {@code TextHolderFigure}
 * interface define together the contracts of a smaller framework inside of the
 * JHotDraw framework for  structured drawing editors.<br>
 * Contract: {@link TextHolderFigure}, {@link org.jhotdraw.draw.tool.TextCreationTool},
 * {@link org.jhotdraw.draw.tool.TextAreaCreationTool},
 * {@link org.jhotdraw.draw.tool.TextEditingTool},
 * {@link org.jhotdraw.draw.tool.TextAreaEditingTool}, {@link FloatingTextField},
 * {@link FloatingTextArea}.
 * <hr>
 *
 * @author Werner Randelshofer
 * @version $Id: FloatingTextArea.java -1   $
 */
public class FloatingTextArea {

    /**
     * A scroll pane to allow for vertical scrolling while editing
     */
    protected JScrollPane editScrollContainer;
    /**
     * The actual editor
     */
    protected JTextArea textArea;
    /**
     * The drawing view.
     */
    @Nullable protected DrawingView view;
    @Nullable private TextHolderFigure editedFigure;
    private FigureListener figureHandler = new FigureAdapter() {

        @Override
        public void attributeChanged(FigureEvent e) {
            updateWidget();
        }
    };

    /**
     * Constructor for the FloatingTextArea object
     */
    public FloatingTextArea() {
        textArea = new JTextArea();
        textArea.setWrapStyleWord(true);
        textArea.setLineWrap(true);
        editScrollContainer = new JScrollPane(textArea,
                JScrollPane.VERTICAL_SCROLLBAR_ALWAYS,
                JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
        editScrollContainer.setCursor(Cursor.getPredefinedCursor(Cursor.DEFAULT_CURSOR));
        editScrollContainer.setBorder(BorderFactory.createLineBorder(Color.black));
    }

    /**
     * Creates the overlay within the given container.
     * @param view the DrawingView
     */
    public void createOverlay(DrawingView view) {
        createOverlay(view, null);
    }

    public void requestFocus() {
        textArea.requestFocus();
    }

    /**
     * Creates the overlay for the given Container using a
     * specific font.
     * @param view the DrawingView
     * @param figure the figure holding the text
     */
    public void createOverlay(DrawingView view, @Nullable TextHolderFigure figure) {
        view.getComponent().add(editScrollContainer, 0);
        editedFigure = figure;
        this.view = view;
        if (editedFigure != null) {
            editedFigure.addFigureListener(figureHandler);
            updateWidget();
        }
    }

    protected void updateWidget() {
        Font f = editedFigure.getFont();
        // FIXME - Should scale with fractional value!
        f = f.deriveFont(f.getStyle(), (float) (editedFigure.getFontSize() * view.getScaleFactor()));
        textArea.setFont(f);
        textArea.setForeground(editedFigure.getTextColor());
        textArea.setBackground(editedFigure.getFillColor());
//        textArea.setBounds(getFieldBounds(editedFigure));
    }

    /**
     * Positions and sizes the overlay.
     * @param r the bounding Rectangle2D.Double for the overlay
     * @param text the text to edit
     */
    public void setBounds(Rectangle2D.Double r, String text) {
        textArea.setText(text);
        editScrollContainer.setBounds(view.drawingToView(r));
        editScrollContainer.setVisible(true);
        textArea.setCaretPosition(0);
        textArea.requestFocus();
    }

    /**
     * Gets the text contents of the overlay.
     * @return The text value
     */
    public String getText() {
        return textArea.getText();
    }

    /**
     * Gets the preferred size of the overlay.
     * @param cols Description of the Parameter
     * @return The preferredSize value
     */
    public Dimension getPreferredSize(int cols) {
        return new Dimension(textArea.getWidth(), textArea.getHeight());
    }

    /**
     * Removes the overlay.
     */
    public void endOverlay() {
        view.getComponent().requestFocus();
        if (editScrollContainer != null) {
            editScrollContainer.setVisible(false);
            view.getComponent().remove(editScrollContainer);

            Rectangle bounds = editScrollContainer.getBounds();
            view.getComponent().repaint(bounds.x, bounds.y, bounds.width, bounds.height);
        }
        if (editedFigure != null) {
            editedFigure.removeFigureListener(figureHandler);
            editedFigure = null;
        }
    }

	public void endEdit(TextAreaCreationTool textAreaCreationTool) {
	    if (textAreaCreationTool.typingTarget != null) {
	        textAreaCreationTool.typingTarget.willChange();

	        final TextHolderFigure editedFigure = textAreaCreationTool.typingTarget;
	        final String oldText = textAreaCreationTool.typingTarget.getText();
	        final String newText = getText();

	        if (newText.length() > 0) {
	            textAreaCreationTool.typingTarget.setText(newText);
	        } else {
	            if (textAreaCreationTool.createdFigure != null) {
	                textAreaCreationTool.getDrawing().remove((Figure) textAreaCreationTool.getAddedFigure());
	            // XXX - Fire undoable edit here!!
	            } else {
	                textAreaCreationTool.typingTarget.setText("");
	            }
	        }

	        UndoableEdit edit = new AbstractUndoableEdit() {

	            @Override
	            public String getPresentationName() {
	                ResourceBundleUtil labels = ResourceBundleUtil.getBundle("org.jhotdraw.draw.Labels");
	                return labels.getString("attribute.text.text");
	            }

	            @Override
	            public void undo() {
	                super.undo();
	                editedFigure.willChange();
	                editedFigure.setText(oldText);
	                editedFigure.changed();
	            }

	            @Override
	            public void redo() {
	                super.redo();
	                editedFigure.willChange();
	                editedFigure.setText(newText);
	                editedFigure.changed();
	            }
	        };
	        textAreaCreationTool.getDrawing().fireUndoableEditHappened(edit);

	        textAreaCreationTool.typingTarget.changed();
	        textAreaCreationTool.typingTarget = null;

	        endOverlay();
	    }
	//	        view().checkDamage();
	}
}

